args.command:
python3 - <<'PY'
from pathlib import Path
terms=('attachment','external','stale','refresh','presign','signed','keep')
for p in Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts and p.suffix in {'.go','.md','.yaml','.yml','.toml','.json'}:
        try: lines=p.read_text(errors='ignore').splitlines()
        except: continue
        for i,l in enumerate(lines,1):
            if any(t in l.lower() for t in terms): print(f'{p}:{i}:{l}')
PY

